use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " An atomic storage for a reference counted smart pointer like [`Arc`] or `Option<Arc>`."] # [doc = ""] # [doc = " This is a storage where a smart pointer may live. It can be read and written atomically from"] # [doc = " several threads, but doesn't act like a pointer itself."] # [doc = ""] # [doc = " One can be created [`from`] an [`Arc`]. To get the pointer back, use the"] # [doc = " [`load`](#method.load)."] # [doc = ""] # [doc = " # Note"] # [doc = ""] # [doc = " This is the common generic implementation. This allows sharing the same code for storing"] # [doc = " both `Arc` and `Option<Arc>` (and possibly other similar types)."] # [doc = ""] # [doc = " In your code, you most probably want to interact with it through the"] # [doc = " [`ArcSwap`](type.ArcSwap.html) and [`ArcSwapOption`](type.ArcSwapOption.html) aliases. However,"] # [doc = " the methods they share are described here and are applicable to both of them. That's why the"] # [doc = " examples here use `ArcSwap` ‒ but they could as well be written with `ArcSwapOption` or"] # [doc = " `ArcSwapAny`."] # [doc = ""] # [doc = " # Type parameters"] # [doc = ""] # [doc = " * `T`: The smart pointer to be kept inside. This crate provides implementation for `Arc<_>` and"] # [doc = "   `Option<Arc<_>>` (`Rc` too, but that one is not practically useful). But third party could"] # [doc = "   provide implementations of the [`RefCnt`] trait and plug in others."] # [doc = " * `S`: Chooses the [strategy] used to protect the data inside. They come with various"] # [doc = "   performance trade offs, the default [`DefaultStrategy`] is good rule of thumb for most use"] # [doc = "   cases."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use std::sync::Arc;"] # [doc = " # use arc_swap::ArcSwap;"] # [doc = " let arc = Arc::new(42);"] # [doc = " let arc_swap = ArcSwap::from(arc);"] # [doc = " assert_eq!(42, **arc_swap.load());"] # [doc = " // It can be read multiple times"] # [doc = " assert_eq!(42, **arc_swap.load());"] # [doc = ""] # [doc = " // Put a new one in there"] # [doc = " let new_arc = Arc::new(0);"] # [doc = " assert_eq!(42, *arc_swap.swap(new_arc));"] # [doc = " assert_eq!(0, **arc_swap.load());"] # [doc = " ```"] # [doc = ""] # [doc = " # Known bugs"] # [doc = ""] # [doc = " Currently, things like `ArcSwapAny<Option<Option<Arc<_>>>>` (notice the double Option) don't"] # [doc = " work properly. A proper solution is being looked into"] # [doc = " ([#81](https://github.com/vorner/arc-swap/issues))."] # [doc = ""] # [doc = " [`Arc`]: https://doc.rust-lang.org/std/sync/struct.Arc.html"] # [doc = " [`from`]: https://doc.rust-lang.org/nightly/std/convert/trait.From.html#tymethod.from"] # [doc = " [`RefCnt`]: trait.RefCnt.html"] pub struct ArcSwapAny < T : RefCnt , S : Strategy < T > = DefaultStrategy > { # [doc = " The actual pointer, extracted from the Arc."] ptr : AtomicPtr < T :: Base > , # [doc = " We are basically an Arc in disguise. Inherit parameters from Arc by pretending to contain"] # [doc = " it."] _phantom_arc : PhantomData < T > , # [doc = " Strategy to protect the data."] strategy : S , }